def request_with_retries(
    api_client,
    endpoint: str,
    params: Dict[str, Any],
    retry_cfg: Dict[str, Any],
):
    """
    Execute GET with retry on transient 5xx errors.
    """
    retries = retry_cfg.get("retries", 2)
    backoff = retry_cfg.get("backoff_seconds", 0.25)
    last_exc: Optional[Exception] = None

    for attempt in range(retries + 1):
        try:
            resp = api_client.get(endpoint=endpoint, params=params)
            # Retry if 5xx
            if 500 <= resp.status_code < 600 and attempt < retries:
                time.sleep(backoff * (attempt + 1))
                continue
            return resp
        except Exception as e:
            last_exc = e
            if attempt < retries:
                time.sleep(backoff * (attempt + 1))
                continue
            raise
    if last_exc:
        raise last_exc

